 * Build a deterministic rAF: enqueue every `raf()` callback into
 * a JS-controlled array so the test can drain them by hand.
 *
 * Returns:
 *   - `raf` / `caf` — the schedulers to pass to `startFrameLoop`.
 *   - `tickAll()` — drain all pending rAFs once (sync).
 *   - `tickUntilDone()` — keep draining while anything remains.
 *   - `ticks` — number of rAFs scheduled so far.
 */
function makeRaf(): {
  raf: (cb: (t: number) => void) => number;
  caf: (h: number) => void;
  tickAll: () => void;
  tickUntilDone: () => void;
  ticks: () => number;
  setNow: (ms: number) => void;
  now: () => number;
} {
  const queue: Array<(t: number) => void> = [];
  let nextHandle = 1;
  const cancelled = new Set<number>();
  const setTimes: number[] = [];
  let nowMs = 0;
  const raf = (cb: (t: number) => void): number => {
    const h = nextHandle++;
    queue.push(cb);
    setTimes.push(nowMs);
    return h;
  };
  const caf = (h: number): void => {
    cancelled.add(h);
  };
  const tickAll = (): void => {
    const ready = queue.splice(0, queue.length).filter((_cb, i) => {
      const h = i + 1;
      return !cancelled.has(h);
    });
    for (const cb of ready) {
      cb(nowMs);
    }
  };
  const tickUntilDone = (): void => {
    let safety = 100;
    while (queue.length > 0 && safety-- > 0) {
      tickAll();
    }
  };
  return {
    raf,
    caf,
    tickAll,
    tickUntilDone,
    ticks: () => setTimes.length,
    now: () => nowMs,
    setNow: (ms: number) => {
      nowMs = ms;
    },
  };
